#!/usr/bin/env bash
# Run dbt locally with the project's config. Needs: gcloud auth application-default login
# Usage: scripts/run-dbt.sh build | run | test | debug | docs generate ...   (any dbt args)
set -euo pipefail
root=$(cd "$(dirname "$0")/.." && pwd)
set -a; source "$root/bootstrap/.env"; set +a   # PROJECT_ID, REGION -> env_var() in profiles/catalogs
# Policy tag IDs for gold.yml (generated by Terraform; they contain the project id, so not in git).
tax=$(gcloud data-catalog taxonomies list --location="$REGION" --project="$PROJECT_ID" \
  --filter='displayName=pii' --format='value(name)')
[ -n "$tax" ] || { echo "taxonomy 'pii' not found: apply terraform first" >&2; exit 1; }
tags=$(gcloud data-catalog taxonomies policy-tags list --taxonomy="$tax" --location="$REGION" \
  --format='csv[no-heading](displayName,name)')
export PII_HIGH_TAG=$(grep '^high,' <<<"$tags" | cut -d, -f2)
export PII_MEDIUM_TAG=$(grep '^medium,' <<<"$tags" | cut -d, -f2)
cd "$root/dbt"
[ -d .venv ] || uv venv .venv --python 3.13 -q        # needs uv: brew install uv
uv pip install -q -p .venv -r requirements.txt          # no-op unless requirements.txt changed
exec .venv/bin/dbt "$@" --profiles-dir .
